DECLARE @source TABLE(source_key nvarchar(200),codigo nvarchar(100),terminal nvarchar(300),grupo nvarchar(150));
INSERT INTO @source(source_key,codigo,terminal,grupo)
SELECT sourceKey,codigo,terminal,grupo FROM OPENJSON(@sports) WITH(sourceKey nvarchar(200),codigo nvarchar(100),terminal nvarchar(300),grupo nvarchar(150));

-- 1. Actualiza primero las agencias que ya tienen la clave SPORT exacta.
UPDATE a SET a.codigo=s.codigo,a.terminal=s.terminal,a.grupo=s.grupo,a.region=N'SPORT',a.is_active=1,a.updated_at=SYSUTCDATETIME()
FROM dbo.agencies a INNER JOIN @source s ON a.source_key=s.source_key;

-- 2. Si la agencia existe por código con otra clave de origen, conserva esa clave única.
-- Esto evita colisiones cuando una carga anterior creó dos referencias para la misma agencia.
UPDATE a SET a.terminal=s.terminal,a.grupo=s.grupo,a.region=N'SPORT',a.is_active=1,a.updated_at=SYSUTCDATETIME()
FROM dbo.agencies a INNER JOIN @source s ON a.codigo=s.codigo
WHERE a.source_key<>s.source_key
  AND NOT EXISTS(SELECT 1 FROM dbo.agencies exacta WHERE exacta.source_key=s.source_key);

INSERT INTO dbo.agencies(id,source_key,codigo,terminal,grupo,region,is_active,status)
SELECT CONVERT(char(36),NEWID()),s.source_key,s.codigo,s.terminal,s.grupo,N'SPORT',1,'PENDING'
FROM @source s
WHERE NOT EXISTS(SELECT 1 FROM dbo.agencies a WHERE a.source_key=s.source_key)
  AND NOT EXISTS(SELECT 1 FROM dbo.agencies a WHERE a.codigo=s.codigo);

COMMIT TRANSACTION;
SELECT grupo,COUNT(*) AS agencias_sport FROM dbo.agencies WHERE source_key LIKE N'SPORT:%' GROUP BY grupo ORDER BY grupo;
